#include <iostream>
#include <iomanip>

int main() {
    int a[3][4] = {{3, -2, 5, 1}, {-4, 7, 0, 6}, {2, 9, -8, -3}};
    int b[4][2] = {{1, 4}, {-5, 2}, {6, -1}, {0, 7}};
    for (int i = 0; i < 3; i++) {
        int row[2] = {0};
        for (int j = 0; j < 2; j++) {
            for (int k = 0; k < 4; k++)
                row[j] += a[i][k] * b[k][j];

        }
        for (int value : row) std::cout << std::setw(5) << value;
        std::cout << '\n';
    }
}
